     2→import { WaveformCanvas } from "../shared/WaveformCanvas";
     3→import type { RGBWaveform, Section } from "../../types";
     4→
     5→const WINDOW_SECONDS = 12;
     6→
     7→export interface DeckWaveformProps {
     8→  waveform: RGBWaveform;
     9→  sections: Section[];
    10→  duration: number;
    11→  /** Current playback position in milliseconds, or null when stopped. */
    12→  positionMs: number | null;
    13→}
    14→
    15→export function DeckWaveform({ waveform, sections, duration, positionMs }: DeckWaveformProps) {
    16→  const cursorSec = positionMs !== null ? positionMs / 1000 : null;
    17→
    18→  const { viewStart, viewEnd } = useMemo(() => {
    19→    if (cursorSec === null) {
    20→      return { viewStart: 0, viewEnd: Math.min(WINDOW_SECONDS, duration) };
    21→    }
    22→    const half = WINDOW_SECONDS / 2;
    23→    const start = Math.max(0, cursorSec - half);
    24→    const end = Math.min(duration, cursorSec + half);
    25→    return { viewStart: start, viewEnd: end };
    26→  }, [cursorSec, duration]);
    27→
    28→  const currentSectionIndex = useMemo(() => {
    29→    if (cursorSec === null || !sections) return null;
    30→    const idx = sections.findIndex(
    31→      (s) => cursorSec >= s.start && cursorSec < s.end,
    32→    );
    33→    return idx >= 0 ? idx : null;
    34→  }, [cursorSec, sections]);
    35→
    36→  return (
    37→    <WaveformCanvas
    38→      waveform={waveform}
    39→      sections={sections}
    40→      duration={duration}
    41→      viewStart={viewStart}
    42→      viewEnd={viewEnd}
    43→      cursorPosition={cursorSec}
    44→      highlightedSection={currentSectionIndex}
    45→      selectedSection={null}
    46→    />
    47→  );
    48→}
    49→'}]}

